def dict_filter(input_dict, n):
    """
    Filters a dictionary to include only entries with values greater than or equal to n.

    Args:
        input_dict (dict): The dictionary to filter.
        n (int): The threshold value.

    Returns:
        dict: A new dictionary with filtered key-value pairs.
    """
    return {key: value for key, value in input_dict.items() if value >= n}

# Example usage with test cases
assert dict_filter({'Cierra Vega': 175, 'Alden Cantrell': 180, 'Kierra Gentry': 165, 'Pierre Cox': 190}, 170) == {'Cierra Vega': 175, 'Alden Cantrell': 180, 'Pierre Cox': 190}
assert dict_filter({}, 170) == {}
assert dict_filter({'Alice': 100, 'Bob': 120}, 150) == {}
assert dict_filter({'Alice': 200, 'Bob': 250}, 150) == {'Alice': 200, 'Bob': 250}
assert dict_filter({'Alice': 150}, 150) == {'Alice': 150}
assert dict_filter({'A': -5, 'B': 0, 'C': 5}, 0) == {'B': 0, 'C': 5}
large_dict = {f'Key{i}': i for i in range(1000)}
assert dict_filter(large_dict, 990) == {f'Key{i}': i for i in range(990, 1000)}
