def max_Product(arr):
    # Handle edge cases
    if len(arr) < 2:
        return None  # Not enough elements for a pair

    # Initialize variables to track the two largest and two smallest numbers
    max1, max2 = float('-inf'), float('-inf')  # Two largest numbers
    min1, min2 = float('inf'), float('inf')  # Two smallest numbers

    # Find the two largest and two smallest numbers in the array
    for num in arr:
        if num > max1:
            max2 = max1
            max1 = num
        elif num > max2:
            max2 = num

        if num < min1:
            min2 = min1
            min1 = num
        elif num < min2:
            min2 = num

    # Compare the products of the two largest and two smallest numbers
    if max1 * max2 >= min1 * min2:
        return (max1, max2)
    else:
        return (min1, min2)

# Example test cases
assert max_Product([1, 2, 3, 4, 7, 0, 8, 4]) == (7, 8)
assert max_Product([-10, -20, 1, 3, 2]) == (-10, -20)
assert max_Product([0, 0, 0]) == (0, 0)
assert max_Product([5]) == None
assert max_Product([]) == None
