def check(n):
    # Helper function to compute the reverse of a number
    def reverse(num):
        return int(str(num)[::-1])

    if n < 0:
        return False  # Negative numbers are not considered

    # Compute the reverse of the number
    reversed_n = reverse(n)

    # Check if the condition is satisfied
    return n == 2 * reversed_n - 1
